-- Owner is deliberately not seeded from an unverified account.
create schema if not exists sovera_private;
revoke all on schema sovera_private from public;
create table sovera_private.admin_original_ids(user_id uuid primary key,old_uid bigint not null);
insert into sovera_private.admin_original_ids select id,uid from public.sovera_profiles;
lock table public.sovera_profiles in access exclusive mode;
alter table public.sovera_profiles drop constraint if exists sovera_uid_six_digits;
alter table public.sovera_profiles alter column uid set generated by default;
do $$ begin
 if exists(select 1 from public.sovera_profiles where uid<10000001) then
  if exists(select 1 from public.sovera_profiles where uid>=10000001) then raise exception 'Mixed ID ranges';end if;
  with n as(select id,10000000+row_number() over(order by created_at,id) as uid from public.sovera_profiles) update public.sovera_profiles p set uid=n.uid from n where p.id=n.id;
 end if;
end $$;
alter table public.sovera_profiles alter column uid set generated always;
alter table public.sovera_profiles add constraint sovera_uid_eight_digits check(uid between 10000001 and 99999999);
do $$ declare n bigint;begin select coalesce(max(uid),10000000)+1 into n from public.sovera_profiles;execute format('alter sequence public.sovera_profiles_uid_seq minvalue 10000001 maxvalue 99999999 start with 10000001 restart with %s no cycle',n);end $$;
alter table public.sovera_profiles add column vip_id text unique check(vip_id ~ '^(0|[1-9][0-9]{0,6})$'),add column vip_expires_at timestamptz,add column is_banned boolean not null default false;
alter table public.sovera_member_cards add column vip_id text,add column vip_expires_at timestamptz;
revoke insert,update on public.sovera_member_cards from authenticated;
grant insert(user_id,uid,display_name,listed,avatar_url,bio,medal_styles),update(user_id,uid,display_name,listed,avatar_url,bio,medal_styles) on public.sovera_member_cards to authenticated;
create function public.sovera_sync_vip_identity() returns trigger language plpgsql security invoker set search_path='' as $$ begin update public.sovera_member_cards set vip_id=new.vip_id,vip_expires_at=new.vip_expires_at where user_id=new.id;return new;end $$;
revoke all on function public.sovera_sync_vip_identity() from public,anon,authenticated;
create trigger sovera_sync_vip after update of vip_id,vip_expires_at on public.sovera_profiles for each row when(old.vip_id is distinct from new.vip_id or old.vip_expires_at is distinct from new.vip_expires_at) execute function public.sovera_sync_vip_identity();
alter table public.sovera_rooms add column is_closed boolean not null default false;
alter table public.sovera_support_tickets add column admin_reply text not null default '' check(char_length(admin_reply)<=3000),add column replied_at timestamptz;

create table public.sovera_admin_staff(
 user_id uuid primary key references public.sovera_profiles(id) on delete cascade,
 role text not null check(role in('owner','manager','admin','agent','room_admin','support')),
 permissions text[] not null default '{}', room_ids uuid[] not null default '{}',
 quota_total bigint not null default 0 check(quota_total>=0),quota_used bigint not null default 0 check(quota_used>=0 and quota_used<=quota_total),
 active boolean not null default true,updated_at timestamptz not null default now()
);
create unique index sovera_one_owner on public.sovera_admin_staff(role) where role='owner';
create table public.sovera_admin_codes(code_hash text primary key,user_id uuid not null references public.sovera_admin_staff(user_id) on delete cascade,expires_at timestamptz not null,created_at timestamptz not null default now());
create table public.sovera_admin_recharges(request_id uuid primary key,actor_id uuid not null references public.sovera_profiles(id),target_id uuid not null references public.sovera_profiles(id),amount bigint not null check(amount between 1 and 1000000000),note text not null default '' check(char_length(note)<=300),created_at timestamptz not null default now());
create table public.sovera_admin_audit(id bigint generated always as identity primary key,actor_id uuid not null,action text not null,target_id uuid,details jsonb not null default '{}',created_at timestamptz not null default now());
create table public.sovera_admin_content(id uuid primary key default gen_random_uuid(),kind text not null check(kind in('banner','notice','gift','frame','entry','medal','tag','event')),title text not null check(char_length(btrim(title)) between 1 and 120),payload jsonb not null default '{}',published boolean not null default false,updated_at timestamptz not null default now());
create index sovera_admin_recharge_actor on public.sovera_admin_recharges(actor_id,created_at desc);
create index sovera_admin_audit_actor on public.sovera_admin_audit(actor_id,created_at desc);
create index sovera_admin_content_kind on public.sovera_admin_content(kind,published);
create index sovera_admin_codes_user on public.sovera_admin_codes(user_id);
do $$ declare t text;begin foreach t in array array['sovera_admin_staff','sovera_admin_codes','sovera_admin_recharges','sovera_admin_audit','sovera_admin_content'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from anon,authenticated',t);execute format('grant all on public.%I to service_role',t);end loop;end $$;
grant usage,select on sequence public.sovera_admin_audit_id_seq to service_role;
grant select on public.sovera_admin_staff to authenticated;
create policy staff_own_read on public.sovera_admin_staff for select to authenticated using(user_id=(select auth.uid()));
grant insert(user_id,code_hash,expires_at) on public.sovera_admin_codes to authenticated;
create policy code_own_create on public.sovera_admin_codes for insert to authenticated with check(user_id=(select auth.uid()) and expires_at<=now()+interval '10 minutes' and exists(select 1 from public.sovera_admin_staff s where s.user_id=(select auth.uid()) and s.active));
grant select on public.sovera_admin_content to anon,authenticated;
create policy published_content_read on public.sovera_admin_content for select to anon,authenticated using(published);

-- A minimal private helper enforces suspension across existing app APIs.
create schema if not exists sovera_private;
revoke all on schema sovera_private from public;
grant usage on schema sovera_private to authenticated,anon;
create function sovera_private.is_blocked() returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.sovera_profiles p where p.id=(select auth.uid()) and p.is_banned) $$;
revoke all on function sovera_private.is_blocked() from public;
grant execute on function sovera_private.is_blocked() to authenticated,anon;
do $$ declare t record;begin for t in select tablename from pg_tables where schemaname='public' and tablename like 'sovera_%' loop execute format('create policy sovera_ban_guard on public.%I as restrictive for all to authenticated using(not (select sovera_private.is_blocked())) with check(not (select sovera_private.is_blocked()))',t.tablename);end loop;end $$;

create function public.sovera_create_admin_code() returns text language plpgsql security invoker set search_path='' as $$
declare c text;begin
 if auth.uid() is null or not exists(select 1 from public.sovera_admin_staff where user_id=auth.uid() and active) then raise exception 'Admin access is not assigned';end if;
 c:=replace(gen_random_uuid()::text,'-','')||replace(gen_random_uuid()::text,'-','');
 insert into public.sovera_admin_codes(user_id,code_hash,expires_at) values(auth.uid(),encode(extensions.digest(c,'sha256'),'hex'),now()+interval '5 minutes');return c;
end $$;
revoke all on function public.sovera_create_admin_code() from public,anon;
grant execute on function public.sovera_create_admin_code() to authenticated;

-- Only the authenticated Edge gateway may redeem codes or run administration.
create function public.sovera_admin_redeem(p_hash text) returns uuid language plpgsql security invoker set search_path='' as $$
declare u uuid;begin
 delete from public.sovera_admin_codes c using public.sovera_admin_staff s,public.sovera_profiles p where c.code_hash=p_hash and c.expires_at>now() and s.user_id=c.user_id and s.active and p.id=s.user_id and not p.is_banned returning c.user_id into u;
 if u is null then raise exception 'Invalid or expired login code';end if;
 insert into public.sovera_admin_audit(actor_id,action) values(u,'session.login');return u;
end $$;
revoke all on function public.sovera_admin_redeem(text) from public,anon,authenticated;
grant execute on function public.sovera_admin_redeem(text) to service_role;

create function public.sovera_admin_run(p_actor uuid,p_action text,p_data jsonb default '{}') returns jsonb language plpgsql security invoker set search_path='' as $$
declare s public.sovera_admin_staff;target public.sovera_profiles;other public.sovera_admin_staff; result jsonb;perm text;amount bigint;rid uuid;prior public.sovera_admin_recharges;role_name text;perms text[];scope uuid[];budget bigint;item public.sovera_admin_content;kind_name text;room public.sovera_rooms;ticket public.sovera_support_tickets;
begin
 select * into s from public.sovera_admin_staff where user_id=p_actor and active for update;
 if not found or exists(select 1 from public.sovera_profiles where id=p_actor and is_banned) then raise exception 'Admin access revoked';end if;
 if p_action='session' then return to_jsonb(s)||jsonb_build_object('quota_remaining',(s.quota_total-s.quota_used)::text,'profile',(select jsonb_build_object('uid',uid,'vip_id',vip_id,'display_name',display_name) from public.sovera_profiles where id=p_actor));end if;
 perm:=case p_action when 'dashboard' then 'dashboard.read' when 'users' then 'users.read' when 'user' then 'users.read' when 'user.ban' then 'users.moderate' when 'user.vip' then 'vip.manage' when 'staff' then 'staff.manage' when 'staff.save' then 'staff.manage' when 'recharge' then 'recharge.create' when 'history' then 'history.read' when 'audit' then 'audit.read' when 'rooms' then 'rooms.manage' when 'room.save' then 'rooms.manage' when 'content' then 'content.manage' when 'content.save' then case when p_data->>'kind'='event' then 'events.manage' else 'content.manage' end when 'support' then 'support.manage' when 'support.reply' then 'support.manage' else null end;
 if p_action='content' and s.role<>'owner' and not 'content.manage'=any(s.permissions) and 'events.manage'=any(s.permissions) then perm:='events.manage';end if;
 if perm is null then raise exception 'Unknown action';end if;
 if s.role<>'owner' and not perm=any(s.permissions) then raise exception 'Permission denied: %',perm;end if;
 if p_action in('staff','staff.save') and s.role<>'owner' then raise exception 'Only the owner manages staff';end if;
 if p_action='dashboard' then
  return jsonb_build_object('users',(select count(*) from public.sovera_profiles),'rooms',(select count(*) from public.sovera_rooms where not is_closed),'staff',(select count(*) from public.sovera_admin_staff where active),'coins',(select coalesce(sum(coin_delta),0)::text from public.sovera_wallet_entries),'diamonds',(select coalesce(sum(diamond_delta),0)::text from public.sovera_wallet_entries),'recharged',(select coalesce(sum(amount),0)::text from public.sovera_admin_recharges),'open_tickets',(select count(*) from public.sovera_support_tickets where status='open'));
 elsif p_action='users' then
  select coalesce(jsonb_agg(to_jsonb(p)),'[]') into result from(select id,uid,vip_id,display_name,avatar_url,country,is_banned,created_at from public.sovera_profiles where
   coalesce(p_data->>'query','')='' or (p_data->>'mode'='vip' and vip_id=p_data->>'query') or (coalesce(p_data->>'mode','uid')='uid' and uid::text=p_data->>'query') or(p_data->>'mode'='name' and strpos(lower(display_name),lower(p_data->>'query'))>0)
   order by uid limit 50 offset least(greatest(coalesce((p_data->>'offset')::int,0),0),100000))p;return result;
 elsif p_action in('user','user.ban','user.vip','recharge','staff.save') then
  select * into target from public.sovera_profiles where id=(p_data->>'target')::uuid for update;
  if not found then raise exception 'User not found';end if;
  if p_action='user' then return to_jsonb(target)||jsonb_build_object('wallet',(select to_jsonb(b) from public.sovera_wallet_balances b where b.user_id=target.id),'staff',(select to_jsonb(a) from public.sovera_admin_staff a where a.user_id=target.id));end if;
  if p_action='user.ban' then
   if target.id=p_actor or exists(select 1 from public.sovera_admin_staff where user_id=target.id and role='owner') or(s.role<>'owner' and exists(select 1 from public.sovera_admin_staff where user_id=target.id)) then raise exception 'Protected account';end if;
   update public.sovera_profiles set is_banned=(p_data->>'banned')::boolean where id=target.id;
  elsif p_action='user.vip' then
   if s.role<>'owner' and exists(select 1 from public.sovera_admin_staff where user_id=target.id and role='owner') then raise exception 'Protected account';end if;
   update public.sovera_profiles set vip_id=nullif(btrim(p_data->>'vip_id'),''),vip_expires_at=case when nullif(btrim(p_data->>'vip_id'),'') is null then null else nullif(p_data->>'vip_expires_at','')::timestamptz end where id=target.id;
  elsif p_action='staff.save' then
   if exists(select 1 from public.sovera_admin_staff where user_id=target.id and role='owner') then raise exception 'Owner account cannot be changed here';end if;
   role_name:=p_data->>'role';if role_name not in('manager','admin','agent','room_admin','support') then raise exception 'Invalid staff role';end if;
   select coalesce(array_agg(v),'{}') into perms from jsonb_array_elements_text(coalesce(p_data->'permissions','[]'))v;
   if not perms<@array['dashboard.read','users.read','users.moderate','vip.manage','recharge.create','history.read','audit.read','rooms.manage','content.manage','events.manage','support.manage']::text[] then raise exception 'Invalid permissions';end if;
   select coalesce(array_agg(v::uuid),'{}') into scope from jsonb_array_elements_text(coalesce(p_data->'room_ids','[]'))v;
   budget:=coalesce((p_data->>'quota')::bigint,0);if budget<0 or budget>1000000000000 then raise exception 'Invalid quota';end if;
   select * into other from public.sovera_admin_staff where user_id=target.id for update;
   if found and budget<other.quota_used then raise exception 'Quota cannot be below already used coins';end if;
   insert into public.sovera_admin_staff(user_id,role,permissions,room_ids,quota_total,active) values(target.id,role_name,perms,scope,budget,coalesce((p_data->>'active')::boolean,true)) on conflict(user_id) do update set role=excluded.role,permissions=excluded.permissions,room_ids=excluded.room_ids,quota_total=excluded.quota_total,active=excluded.active,updated_at=now();
   insert into public.sovera_reseller_accounts(user_id,status,coin_quota,used_quota) values(target.id,case when coalesce((p_data->>'active')::boolean,true) then 'active' else 'suspended' end,budget,coalesce(other.quota_used,0)) on conflict(user_id) do update set status=excluded.status,coin_quota=excluded.coin_quota,used_quota=excluded.used_quota,updated_at=now();
  elsif p_action='recharge' then
   amount:=(p_data->>'amount')::bigint;rid:=(p_data->>'request_id')::uuid;
   if amount is null or amount<1 or amount>1000000000 or rid is null then raise exception 'Invalid recharge';end if;
   perform pg_advisory_xact_lock(hashtextextended(rid::text,417));
   select * into prior from public.sovera_admin_recharges where request_id=rid;
   if found then if prior.actor_id<>p_actor or prior.target_id<>target.id or prior.amount<>amount then raise exception 'Request ID already used for another recharge';end if;return jsonb_build_object('request_id',rid,'duplicate',true,'uid',target.uid,'amount',amount::text);end if;
   if target.is_banned then raise exception 'Recipient suspended';end if;
   if s.role<>'owner' and s.quota_total-s.quota_used<amount then raise exception 'Insufficient agent quota';end if;
   insert into public.sovera_wallets(user_id) values(target.id) on conflict do nothing;
   perform 1 from public.sovera_wallets where user_id=target.id and status='active' for update;if not found then raise exception 'Wallet frozen';end if;
   insert into public.sovera_admin_recharges(request_id,actor_id,target_id,amount,note) values(rid,p_actor,target.id,amount,left(coalesce(p_data->>'note',''),300));
   insert into public.sovera_wallet_entries(user_id,coin_delta,kind,reference) values(target.id,amount,'recharge','admin:'||rid::text);
   if s.role<>'owner' then update public.sovera_admin_staff set quota_used=quota_used+amount where user_id=p_actor;update public.sovera_reseller_accounts set used_quota=used_quota+amount where user_id=p_actor;end if;
   insert into public.sovera_admin_audit(actor_id,action,target_id,details) values(p_actor,p_action,target.id,jsonb_build_object('request_id',rid,'amount',amount::text,'uid',target.uid));
   return jsonb_build_object('request_id',rid,'uid',target.uid,'amount',amount::text,'balance',(select coins from public.sovera_wallet_balances where user_id=target.id),'quota_remaining',case when s.role='owner' then null else (s.quota_total-s.quota_used-amount)::text end);
  end if;
  insert into public.sovera_admin_audit(actor_id,action,target_id,details) values(p_actor,p_action,target.id,p_data-'note');return jsonb_build_object('saved',true);
 elsif p_action='staff' then return(select coalesce(jsonb_agg(to_jsonb(x)),'[]') from(select a.*,p.uid,p.vip_id,p.display_name from public.sovera_admin_staff a join public.sovera_profiles p on p.id=a.user_id order by p.uid)x);
 elsif p_action='history' then return(select coalesce(jsonb_agg(to_jsonb(x)),'[]') from(select r.*,p.uid,p.vip_id,p.display_name from public.sovera_admin_recharges r join public.sovera_profiles p on p.id=r.target_id where s.role='owner' or r.actor_id=p_actor order by r.created_at desc limit 100)x);
 elsif p_action='audit' then return(select coalesce(jsonb_agg(to_jsonb(x)),'[]') from(select * from public.sovera_admin_audit order by id desc limit 100)x);
 elsif p_action='rooms' then return(select coalesce(jsonb_agg(to_jsonb(x)),'[]') from(select r.*,p.uid as owner_uid from public.sovera_rooms r join public.sovera_profiles p on p.id=r.owner_id where s.role<>'room_admin' or r.id=any(s.room_ids) order by r.created_at desc limit 100)x);
 elsif p_action='room.save' then
  select * into room from public.sovera_rooms where id=(p_data->>'id')::uuid for update;
  if not found or(s.role='room_admin' and not room.id=any(s.room_ids)) then raise exception 'Room outside assigned scope';end if;
  update public.sovera_rooms set name=p_data->>'name',seat_count=(p_data->>'seat_count')::int,is_closed=(p_data->>'is_closed')::boolean where id=room.id;
 elsif p_action='content' then return(select coalesce(jsonb_agg(to_jsonb(x)),'[]') from(select * from public.sovera_admin_content where s.role='owner' or 'content.manage'=any(s.permissions) or kind='event' order by updated_at desc limit 100)x);
 elsif p_action='content.save' then
  kind_name:=p_data->>'kind';
  if p_data->>'id' is not null then select * into item from public.sovera_admin_content where id=(p_data->>'id')::uuid for update;if not found or item.kind<>kind_name then raise exception 'Content not found or kind changed';end if;end if;
  if octet_length(coalesce(p_data->'payload','{}')::text)>16000 then raise exception 'Content too large';end if;
  insert into public.sovera_admin_content(id,kind,title,payload,published) values(coalesce((p_data->>'id')::uuid,gen_random_uuid()),kind_name,p_data->>'title',coalesce(p_data->'payload','{}'),coalesce((p_data->>'published')::boolean,false)) on conflict(id) do update set title=excluded.title,payload=excluded.payload,published=excluded.published,updated_at=now();
 elsif p_action='support' then return(select coalesce(jsonb_agg(to_jsonb(x)),'[]') from(select t.*,p.uid,p.display_name from public.sovera_support_tickets t join public.sovera_profiles p on p.id=t.user_id order by t.created_at desc limit 100)x);
 elsif p_action='support.reply' then
  select * into ticket from public.sovera_support_tickets where id=(p_data->>'id')::uuid for update;if not found then raise exception 'Ticket not found';end if;
  update public.sovera_support_tickets set admin_reply=p_data->>'reply',status=p_data->>'status',replied_at=now() where id=ticket.id;
 end if;
 insert into public.sovera_admin_audit(actor_id,action,details) values(p_actor,p_action,p_data);return jsonb_build_object('saved',true);
end $$;
revoke all on function public.sovera_admin_run(uuid,text,jsonb) from public,anon,authenticated;
grant execute on function public.sovera_admin_run(uuid,text,jsonb) to service_role;
grant select,insert,update on public.sovera_profiles,public.sovera_member_cards,public.sovera_rooms,public.sovera_support_tickets,public.sovera_reseller_accounts to service_role;
notify pgrst,'reload schema';

create function public.sovera_copy_member_vip() returns trigger language plpgsql security invoker set search_path='' as $$ begin select vip_id,vip_expires_at into new.vip_id,new.vip_expires_at from public.sovera_profiles where id=new.user_id;return new;end $$;
revoke all on function public.sovera_copy_member_vip() from public,anon,authenticated;
create trigger sovera_copy_member_vip before insert on public.sovera_member_cards for each row execute function public.sovera_copy_member_vip();
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('sovera-admin-assets','sovera-admin-assets',true,10485760,array['image/png','image/jpeg','image/webp','video/mp4','audio/mpeg','audio/wav']) on conflict(id) do nothing;

create function public.sovera_account_status() returns boolean language sql stable security invoker set search_path='' as $$ select sovera_private.is_blocked() $$;
revoke all on function public.sovera_account_status() from public,anon;
grant execute on function public.sovera_account_status() to authenticated;
